--     /courses/cyber-security body text: "top IT companies"
--     /corporate-training body text: "500+ COMPANIES"
-- Allowed claims only: since 2010, 5,000+ students trained, 50+ hiring partners, 1-year LMS access.
--
-- Run the steps in order: 0 → 1 → 2 → 3 → 4. Each can be run on its own (the
-- helper is a normal function, so it survives separate SQL Editor runs; step 4 drops it).
-- The SQL Editor shows only the last result: run each SELECT on its own to see it.

-- ── STEP 0: helper function (dropped in step 4) ────────────────────────────
CREATE OR REPLACE FUNCTION public.coss_claims_fix_20261003(t text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $fn$
DECLARE
  s text := t;
BEGIN
  IF s IS NULL THEN RETURN NULL; END IF;
  -- 1. Seeded blog suffix (also when cut short with "…").
  IF s ~* '\s*—\s*Expert IT training insights from Coss Cloud Solutions, Hyderabad''s leading IT.*$' THEN
    s := regexp_replace(s, '\s*—\s*Expert IT training insights from Coss Cloud Solutions, Hyderabad''s leading IT.*$', '', 'i');
    IF length(s) + 43 <= 158 THEN s := s || ' — Expert IT training insights, since 2010.'; END IF;
  END IF;
  -- 2. Literal phrase pairs, longest first.
  s := replace(s, 'With our 15+ years of experience, we prepare you for the exam and the real-world demands of companies in HITEC City and Gachibowli, ensuring you''re ready for placements.', 'Training IT professionals since 2010, we prepare you for the exam and the real-world demands of companies in HITEC City and Gachibowli.');
