-- ── STEP 1: PREVIEW (read-only) — old and new text side by side ────────────
-- Expected: PageSeo rows for blog posts (seeded suffix, "Best … Institute" titles),
-- course pages (job-outcome sentences) and home/about/why-us (up to ~100 pages);
-- Course: 23 rows (cmq587yfc0002uhify94y0moo, cmq588dkz0003uhif3doslfiq, cmq59akvb000452fmxxk7gzuy, cmq5jnctt00023hrq18225pvx, cmq59g60f000g52fmmshel3in, cmq247cm0000xnmi59qz1w2ye, cmq2fluew001hxd37ive4oubj, cmq5jr6810000h4xj8jde9ytt, cmpieh0ag0002552d70bd1454, cmpkvqetn0007x26h0i2jczpu, cmq2fapry0001xd37y78galtj, cmq59gyrp000i52fmexblzbui, cmq5jssqb0000uaorxf4qf2gi, cmq599j6d000152fm3ky0nabx, cmq2455fc000nnmi5wefkjabm, cmq59hqvw000k52fmjio8kbko, cmq2fe1x7000hxd377uxnu99r, cmq246ziy000vnmi5pya46pzb, cmq2p0lds000327uftxhsvk8y, cmq59ctzw000952fmk18xvxgy, cmq2fjefp0015xd370xcdo9fd, cmq5997qn000052fm5v790tat, cmq241wdf0009nmi52tt7l2uh);
-- BlogPost: 4 rows (cmr8du7wr00025xxkiiw2wks4, cmpieh1qz0004552dfsgmaf0v, cmr8ecpcd0000hdk9a1isiag7, cmr8e725r00035xxkaqoq6ylg).
SELECT 'PageSeo' AS tbl, "pageSlug" AS key, col, old, public.coss_claims_fix_20261003(old) AS new
FROM "PageSeo", LATERAL (VALUES ('metaTitle', "metaTitle"), ('metaDescription', "metaDescription"), ('ogTitle', "ogTitle"), ('ogDescription', "ogDescription")) v(col, old)
WHERE old IS DISTINCT FROM public.coss_claims_fix_20261003(old)
UNION ALL
SELECT 'Course', id || ' ' || slug, col, old, public.coss_claims_fix_20261003(old)
FROM "Course", LATERAL (VALUES ('title', title), ('excerpt', excerpt), ('description', description), ('seoTitle', "seoTitle"), ('seoDesc', "seoDesc")) v(col, old)
WHERE old IS DISTINCT FROM public.coss_claims_fix_20261003(old)
UNION ALL
SELECT 'Course', id || ' ' || slug, 'highlights[' || i || ']', x, public.coss_claims_fix_20261003(x)
FROM "Course", unnest(highlights) WITH ORDINALITY AS u(x, i)
WHERE x IS DISTINCT FROM public.coss_claims_fix_20261003(x)
UNION ALL
SELECT 'BlogPost', id || ' ' || slug, col, old, public.coss_claims_fix_20261003(old)
FROM "BlogPost", LATERAL (VALUES ('title', title), ('excerpt', excerpt), ('seoTitle', "seoTitle"), ('seoDesc', "seoDesc")) v(col, old)
WHERE old IS DISTINCT FROM public.coss_claims_fix_20261003(old)
ORDER BY 1, 2, 3;

-- ── STEP 2: UPDATE … RETURNING (one transaction) ───────────────────────────
BEGIN;

UPDATE "PageSeo" SET
  "metaTitle" = public.coss_claims_fix_20261003("metaTitle"),
  "metaDescription" = public.coss_claims_fix_20261003("metaDescription"),
  "ogTitle" = public.coss_claims_fix_20261003("ogTitle"),
  "ogDescription" = public.coss_claims_fix_20261003("ogDescription"),
  "updatedAt" = now()
WHERE "metaTitle" IS DISTINCT FROM public.coss_claims_fix_20261003("metaTitle")
   OR "metaDescription" IS DISTINCT FROM public.coss_claims_fix_20261003("metaDescription")
   OR "ogTitle" IS DISTINCT FROM public.coss_claims_fix_20261003("ogTitle")
   OR "ogDescription" IS DISTINCT FROM public.coss_claims_fix_20261003("ogDescription")
RETURNING 'PageSeo' AS tbl, "pageSlug", "metaTitle", "metaDescription", "ogTitle", "ogDescription";

UPDATE "Course" SET
  title = public.coss_claims_fix_20261003(title),
  excerpt = public.coss_claims_fix_20261003(excerpt),
  description = public.coss_claims_fix_20261003(description),
  "seoTitle" = public.coss_claims_fix_20261003("seoTitle"),
  "seoDesc" = public.coss_claims_fix_20261003("seoDesc"),
  highlights = ARRAY(SELECT public.coss_claims_fix_20261003(x) FROM unnest(highlights) WITH ORDINALITY AS u(x, i) ORDER BY i),
  "updatedAt" = now()
WHERE "title" IS DISTINCT FROM public.coss_claims_fix_20261003("title")
   OR "excerpt" IS DISTINCT FROM public.coss_claims_fix_20261003("excerpt")
   OR "description" IS DISTINCT FROM public.coss_claims_fix_20261003("description")
   OR "seoTitle" IS DISTINCT FROM public.coss_claims_fix_20261003("seoTitle")
   OR "seoDesc" IS DISTINCT FROM public.coss_claims_fix_20261003("seoDesc")
   OR "highlights" IS DISTINCT FROM ARRAY(SELECT public.coss_claims_fix_20261003(x) FROM unnest("highlights") WITH ORDINALITY AS u(x, i) ORDER BY i)
RETURNING 'Course' AS tbl, id, slug, "seoDesc", excerpt;

UPDATE "BlogPost" SET
  title = public.coss_claims_fix_20261003(title),
  excerpt = public.coss_claims_fix_20261003(excerpt),
  "seoTitle" = public.coss_claims_fix_20261003("seoTitle"),
  "seoDesc" = public.coss_claims_fix_20261003("seoDesc"),
  "updatedAt" = now()
WHERE "title" IS DISTINCT FROM public.coss_claims_fix_20261003("title")
   OR "excerpt" IS DISTINCT FROM public.coss_claims_fix_20261003("excerpt")
   OR "seoTitle" IS DISTINCT FROM public.coss_claims_fix_20261003("seoTitle")
   OR "seoDesc" IS DISTINCT FROM public.coss_claims_fix_20261003("seoDesc")
RETURNING 'BlogPost' AS tbl, id, slug, "seoDesc", excerpt;

COMMIT;

