UNION ALL
SELECT 'BlogPost', count(*) FROM "BlogPost" WHERE "title" IS DISTINCT FROM public.coss_claims_fix_20261003("title")
   OR "excerpt" IS DISTINCT FROM public.coss_claims_fix_20261003("excerpt")
   OR "seoTitle" IS DISTINCT FROM public.coss_claims_fix_20261003("seoTitle")
